{
  "name": "flowstate",
  "version": "0.1.0",
  "author": {
    "name": "picatz"
  },
  "description": "Write, test, and debug Flowstate Flowfiles from Claude Code: the flow MCP server, authoring skills, and a live validation pane.",
  "types": "./types/index.d.ts",
  "userConfig": {
    "flowBinary": {
      "type": "string",
      "title": "flow binary",
      "description": "The flow executable the mod runs to validate Flowfiles.",
      "default": "flow"
    },
    "validateOnEdit": {
      "type": "boolean",
      "title": "Validate after edits",
      "description": "Run flow validate after Claude edits a Flowfile and tell the model what is wrong.",
      "default": true
    },
    "guardServerActions": {
      "type": "boolean",
      "title": "Confirm server actions",
      "description": "Ask before Claude runs a flow verb that changes a server (run, signal, cancel, terminate, schedule changes), naming the verb and the server address.",
      "default": true
    },
    "verifyBeforeDone": {
      "type": "boolean",
      "title": "Remind to verify",
      "description": "Once per turn, remind Claude to run flow validate (or flow test, when a suite exists) before it finishes if it edited a Flowfile and none has passed since.",
      "default": true
    }
  }
}

